.vlm-gp-collection--sale .vlm-gp-toolbar{border-top:0;margin-top:8px}
.vlm-gp-collection--sale .nm-fs-card-cta{display:inline-block;margin-top:12px;padding:11px 14px;background:#16140f;color:#fff!important;text-decoration:none;font:600 11px/1 Arial,Helvetica,sans-serif;letter-spacing:.08em;text-transform:uppercase}
.vlm-gp-collection--sale .vlm-gp-card{border:0;border-bottom:1px solid #ece7df;padding-bottom:8px}
.vlm-gp-collection--sale .vlm-gp-card-image{background:#f4f1eb}
.nm-fs-sticky-mid-short{display:none}
/* Override theme announcement column stack on mobile */
@media (max-width:900px){
  .vg-announcement{
    display:block!important;
    text-align:center!important;
    white-space:nowrap!important;
    overflow:hidden!important;
    text-overflow:ellipsis!important;
    min-height:0!important;
    padding:9px 14px!important;
    font-size:10px!important;
    line-height:1.35!important;
    letter-spacing:.04em!important;
    max-width:100%!important;
  }
  .vg-announcement .nm-announcement-message,
  .vg-announcement .nm-geo-deadline{display:inline!important}
  .vg-announcement .nm-geo-city{display:none!important} /* city shown in SHIPPING TO rotator */
}
@media (max-width:390px){
  .vg-announcement{font-size:8px!important;padding:8px 10px!important}
}
@media (max-width:980px){
  .nm-fs-hero{grid-template-columns:1fr;min-height:0}
  .nm-fs-hero-media{min-height:260px;order:-1}
  .nm-fs-hero-media::after{background:linear-gradient(180deg,rgba(18,15,12,.12),rgba(18,15,12,.72))}
  .nm-fs-hero-panel{padding:48px 28px 52px}
  .nm-fs-title{font-size:58px;line-height:.98}
  .nm-fs-lede{margin-top:16px;font-size:20px;line-height:1.35;max-width:none}
  .nm-fs-offer{margin-top:26px;padding-top:20px}
  .nm-fs-offer li{padding:0 0 10px;font-size:18px}
  .nm-fs-hero-actions{margin-top:28px;gap:14px}
  .nm-fs-sticky{gap:10px;padding:10px 14px}
  .nm-fs-sticky-mid{font-size:11px;line-height:1.35}
}
@media (max-width:749px){
  .nm-fs-sticky{
    flex-wrap:wrap;
    justify-content:center;
    gap:8px;
    padding:10px 12px 12px;
  }
  .nm-fs-sticky-label{display:none}
  .nm-fs-sticky-mid{
    flex:1 1 100%;
    text-align:center;
    order:1;
    font-size:11px;
    opacity:.95;
  }
  .nm-fs-sticky-mid-full{display:none}
  .nm-fs-sticky-mid-short{display:inline}
  .nm-fs-sticky-cta{
    flex:1 1 100%;
    order:2;
    text-align:center;
    padding:12px 16px;
    font-size:12px;
  }
  .nm-fs-hero-media{min-height:200px}
  .nm-fs-hero-panel{padding:44px 22px 48px}
  .nm-fs-eyebrow{margin-bottom:18px;font-size:11px;letter-spacing:.16em}
  .nm-fs-title{font-size:52px;line-height:.96}
  .nm-fs-lede{margin-top:14px;font-size:20px;line-height:1.3;color:#f4efe6}
  .nm-fs-city-wrap{display:none}
  .nm-fs-offer{margin-top:22px;padding-top:18px}
  .nm-fs-offer li{padding:0 0 8px;font-size:18px;color:#f7f2ea}
  .nm-fs-hero-actions{
    flex-direction:column;
    align-items:stretch;
    gap:14px;
    margin-top:26px;
  }
  .nm-fs-cta{
    text-align:center;
    padding:18px 18px;
    font-size:13px;
    color:#16140f!important;
  }
  .nm-fs-deadline{text-align:center;font-size:14px;line-height:1.4;color:#eadfce}
}
